function elfzwo_icon( $name, $class = 'h-4 w-4', $stroke_width = 2 ) {
	$paths = elfzwo_icon_paths();
	// Das Glitzer-Icon wirkt nach KI-Oberfläche — wo es noch gespeichert ist, wird ein Stern gezeigt.
	if ( 'sparkles' === $name ) {
		$name = 'star';
	}

	if ( ! isset( $paths[ $name ] ) ) {
		return '';
	}

	// Skizzen-Effekt: jede Linie wird ein zweites Mal leicht versetzt, gedreht
	// und dünner nachgezogen, damit die Handzeichnung auch bei 16 px sichtbar ist.
	return sprintf(
		'<svg class="icon %1$s" viewBox="-1.5 -1.5 27 27" fill="none" stroke="currentColor" stroke-width="%2$s" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">%3$s<g stroke-width="%4$s" opacity=".6" transform="rotate(4 12 12) translate(1 -.8)">%3$s</g></svg>',
		esc_attr( $class ),
		esc_attr( $stroke_width ),
		$paths[ $name ],
		esc_attr( round( $stroke_width * 0.6, 2 ) )
	);
}

/**
 * Icon-Keys für Editor-Auswahlfelder (Block-Icon-Picker).
 */
function elfzwo_icon_keys() {
	return array_values( array_diff( array_keys( elfzwo_icon_paths() ), array( 'sparkles' ) ) );
}
